# ── VIP / session helpers ──────────────────────────────────────────────────────

def load_vip() -> dict:
    try:
        return json.loads(VIP_FILE.read_text()) if VIP_FILE.exists() else {}
    except Exception as e:
        logger.warning(f"Could not read VIP data, using empty list: {e}")
        return {}

def save_vip(data: dict):
    temp = VIP_FILE.with_suffix(".tmp")
    temp.write_text(json.dumps(data, indent=2, ensure_ascii=False))
    temp.replace(VIP_FILE)

def is_vip(user_id: int) -> bool:
    vip = load_vip()
    uid = str(user_id)
    if uid not in vip:
        return False
    expiry = vip[uid].get("expiry")
    if expiry is None:
        return True
    try:
        return datetime.fromisoformat(expiry) > datetime.now(timezone.utc)
    except Exception:
        return False

def load_sessions() -> dict:
    try:
        return json.loads(SESSIONS_FILE.read_text()) if SESSIONS_FILE.exists() else {}
    except Exception as e:
        logger.warning(f"Could not read session data, using empty sessions: {e}")
        return {}

def save_sessions(data: dict):
    temp = SESSIONS_FILE.with_suffix(".tmp")
    temp.write_text(json.dumps(data, indent=2))
    temp.replace(SESSIONS_FILE)

def touch_session(user_id: int):
    s = load_sessions()
    s[str(user_id)] = datetime.now(timezone.utc).isoformat()
    save_sessions(s)

def count_active_sessions() -> int:
    s = load_sessions()
    cutoff = datetime.now(timezone.utc) - timedelta(minutes=30)
    return sum(1 for ts in s.values() if datetime.fromisoformat(ts) > cutoff)

def count_expiring_soon() -> int:
    vip = load_vip()
    cutoff = datetime.now(timezone.utc) + timedelta(days=3)
    count = 0
    for d in vip.values():
        exp = d.get("expiry")
        if exp:
            try:
                dt = datetime.fromisoformat(exp)
                if datetime.now(timezone.utc) < dt < cutoff:
                    count += 1
            except Exception:
                pass
    return count

def count_active_vip() -> int:
    vip = load_vip()
    now = datetime.now(timezone.utc)
    count = 0
    for d in vip.values():
        exp = d.get("expiry")
        if exp is None:
            count += 1
        else:
            try:
                if datetime.fromisoformat(exp) > now:
                    count += 1
            except Exception:
                pass
    return count


# ── One-hour daily free access ─────────────────────────────────────────────────

def _today_key() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%d")

def load_free_access() -> dict:
    try:
        return json.loads(FREE_FILE.read_text()) if FREE_FILE.exists() else {}
    except Exception as e:
        logger.warning(f"Could not read free-access data, using empty list: {e}")
        return {}

def save_free_access(data: dict):
    temp = FREE_FILE.with_suffix(".tmp")
    temp.write_text(json.dumps(data, indent=2, ensure_ascii=False))
    temp.replace(FREE_FILE)

def _free_record(data: dict, user_id: int) -> dict | None:
    record = data.get(str(user_id))
    if not isinstance(record, dict) or not record.get("enabled", False):
        return None
    if record.get("date") != _today_key():
        record.update({
            "date": _today_key(),
            "used_seconds": 0,
            "active": False,
            "started_at": None,
        })
    return record

def _free_used_seconds(record: dict) -> int:
    used = max(0, int(record.get("used_seconds", 0)))
    if record.get("active") and record.get("started_at"):
        try:
            started = datetime.fromisoformat(record["started_at"])
            used += max(0, int((datetime.now(timezone.utc) - started).total_seconds()))
        except Exception:
            pass
    return used

def free_remaining_seconds(user_id: int) -> int:
    data = load_free_access()
    old_date = data.get(str(user_id), {}).get("date")
    record = _free_record(data, user_id)
    if record is None:
        return 0
    remaining = max(0, FREE_DAILY_SECONDS - _free_used_seconds(record))
    if remaining == 0 and record.get("active"):
        record["used_seconds"] = FREE_DAILY_SECONDS
        record["active"] = False
        record["started_at"] = None
        save_free_access(data)
    elif old_date != record.get("date"):
        save_free_access(data)
    return remaining

def free_access_enabled(user_id: int) -> bool:
    return free_remaining_seconds(user_id) > 0

def has_signal_access(user_id: int) -> bool:
    return is_vip(user_id) or free_access_enabled(user_id)

def start_free_timer(user_id: int) -> bool:
    data = load_free_access()
    record = _free_record(data, user_id)
    if record is None or _free_used_seconds(record) >= FREE_DAILY_SECONDS:
        return False
    if not record.get("active"):
        record["active"] = True
        record["started_at"] = datetime.now(timezone.utc).isoformat()
        save_free_access(data)
    return True

def pause_free_timer(user_id: int) -> int:
    data = load_free_access()
    record = _free_record(data, user_id)
    if record is None:
        return 0
    record["used_seconds"] = min(FREE_DAILY_SECONDS, _free_used_seconds(record))
    record["active"] = False
    record["started_at"] = None
    save_free_access(data)
    return max(0, FREE_DAILY_SECONDS - record["used_seconds"])

def format_free_time(seconds: int) -> str:
    return f"{seconds // 60}m {seconds % 60}s"

def count_free_access() -> int:
    return sum(
        1 for record in load_free_access().values()
        if isinstance(record, dict) and record.get("enabled", False)
    )

# ── Channel signal storage ─────────────────────────────────────────────────────

def save_channel_signal(
    signal: str,
    source_timestamp: str | None = None,
    source_transaction: str | None = None,
    source_level: int | None = None,
):
    data = {
        "signal": signal,
        "timestamp": source_timestamp or datetime.now(timezone.utc).isoformat(),
        "fetched_at": datetime.now(timezone.utc).isoformat(),
        "source_timestamp": source_timestamp,
        "source_transaction": source_transaction,
        "source_level": source_level,
    }
    temp = CHANNEL_SIG_FILE.with_suffix(".tmp")
    temp.write_text(json.dumps(data))
    temp.replace(CHANNEL_SIG_FILE)
    source_hist = load_source_history()
    if not source_hist or (
        source_hist[-1].get("signal") != signal
        or source_hist[-1].get("timestamp") != data["timestamp"]
    ):
        source_hist.append({
            "signal": signal,
            "timestamp": data["timestamp"],
        })
    temp = SOURCE_HIST_FILE.with_suffix(".tmp")
    temp.write_text(json.dumps(source_hist[-120:], indent=2))
    temp.replace(SOURCE_HIST_FILE)
    logger.info(f"📡 Channel signal saved: {signal}")

def get_channel_signal(max_age_minutes: float = CHANNEL_CACHE_MAX_AGE_MIN) -> str | None:
    if not CHANNEL_SIG_FILE.exists():
        return None
    try:
        data = json.loads(CHANNEL_SIG_FILE.read_text())
        ts   = datetime.fromisoformat(data["timestamp"])
        age  = (datetime.now(timezone.utc) - ts).total_seconds() / 60
        if age <= max_age_minutes:
            return data["signal"]
    except Exception:
        pass
    return None


def load_source_history() -> list:
    try:
        data = json.loads(SOURCE_HIST_FILE.read_text()) if SOURCE_HIST_FILE.exists() else []
        return data if isinstance(data, list) else []
    except Exception as e:
        logger.warning("Could not read source history: %s", e)
        return []


def load_channel_config() -> dict:
    """Load auto-post destinations and the last source post we published."""
    try:
        data = json.loads(CHANNELS_FILE.read_text()) if CHANNELS_FILE.exists() else {}
        if not isinstance(data, dict):
            return {"channels": {}, "auto_post": False, "last_source_timestamp": None}
        data.setdefault("channels", {})
        data.setdefault("auto_post", False)
        data.setdefault("last_source_timestamp", None)
        if not isinstance(data.get("auto_signal_history"), list):
            data["auto_signal_history"] = []
        if not isinstance(data.get("auto_result_history"), list):
            # This is deliberately separate from bot signal history.  Pattern
            # mode must read the actual game outcomes, not the directions the
            # bot happened to post.
            data["auto_result_history"] = []
        return data
    except Exception as error:
        logger.warning("Could not read auto-post configuration: %s", error)
        return {
            "channels": {},
            "auto_post": False,
            "last_source_timestamp": None,
            "auto_signal_history": [],
            "auto_result_history": [],
        }


def save_channel_config(data: dict):
    temp = CHANNELS_FILE.with_suffix(".tmp")
    temp.write_text(json.dumps(data, indent=2, ensure_ascii=False))
    temp.replace(CHANNELS_FILE)


def m2_ladder() -> list[int]:
    """Return the exact M2 table used by auto-post."""
    return M2_LADDER.copy()


def load_mm_state() -> dict:
    """Money-management state: M2 level, cumulative win count and cycle timing."""
    try:
        data = json.loads(MM_STATE_FILE.read_text()) if MM_STATE_FILE.exists() else {}
        if not isinstance(data, dict):
            data = {}
    except Exception as error:
        logger.warning("Could not read money-management state: %s", error)
        data = {}
    data.setdefault("level", 0)
    # win_count = cycle တစ်ခုအတွင်း အနိုင်အရေအတွက် (ရှုံးလည်း 1 က ပြန်မစပါ)
    data.setdefault("win_count", int(data.get("win_streak", 0) or 0))
    data["win_streak"] = data["win_count"]
    # loss_streak = ဆက်တိုက် ရှုံးအရေအတွက် (win တာနဲ့ 0 ပြန်ဖြစ်)
    data.setdefault("loss_streak", 0)
    hours = int(data.get("cycle_hours", DEFAULT_CYCLE_HOURS) or DEFAULT_CYCLE_HOURS)
    data["cycle_hours"] = hours if hours in CYCLE_HOUR_CHOICES else DEFAULT_CYCLE_HOURS
    data.setdefault("cycle_start", datetime.now(timezone.utc).isoformat())
    data.setdefault("paused_until", None)
    data.setdefault("manual_pause", False)
    data.setdefault("manual_resume", False)
    start_time = str(data.get("start_time", DEFAULT_START_TIME))
    close_time = str(data.get("close_time", DEFAULT_CLOSE_TIME))
    valid_times = {value for value, _label in SCHEDULE_TIME_CHOICES}
    data["start_time"] = start_time if start_time in valid_times else DEFAULT_START_TIME
    data["close_time"] = close_time if close_time in valid_times else DEFAULT_CLOSE_TIME
    return data


def save_mm_state(data: dict):
    temp = MM_STATE_FILE.with_suffix(".tmp")
    temp.write_text(json.dumps(data, indent=2))
    temp.replace(MM_STATE_FILE)


def current_bet() -> int:
    ladder = m2_ladder()
    level = load_mm_state().get("level", 0)
    return ladder[min(max(int(level), 0), len(ladder) - 1)]


def get_cycle_hours() -> int:
    return int(load_mm_state().get("cycle_hours", DEFAULT_CYCLE_HOURS))


def set_cycle_hours(hours: int) -> int:
    """Admin ရွေးလိုက်တဲ့ 1H / 2H / 3H ကို သိမ်းပါတယ်။"""
    hours = hours if hours in CYCLE_HOUR_CHOICES else DEFAULT_CYCLE_HOURS
    state = load_mm_state()
    state["cycle_hours"] = hours
    save_mm_state(state)
    return hours


def _schedule_label(value: str) -> str:
    return dict(SCHEDULE_TIME_CHOICES).get(value, value)


def get_schedule() -> tuple[str, str]:
    state = load_mm_state()
    return state["start_time"], state["close_time"]


def set_schedule(start_time: str | None = None, close_time: str | None = None) -> tuple[str, str]:
    """Save the daily signal window in Myanmar local time."""
    valid_times = {value for value, _label in SCHEDULE_TIME_CHOICES}
    state = load_mm_state()
    if start_time in valid_times:
        state["start_time"] = start_time
    if close_time in valid_times:
        state["close_time"] = close_time
    save_mm_state(state)
    return state["start_time"], state["close_time"]


def schedule_is_open(now: datetime | None = None) -> bool:
    """Auto-posting runs 24/7; the daily schedule window is disabled."""
    return True


def _start_new_cycle(state: dict, started_at: datetime | None = None) -> dict:
    state["win_count"] = 0
    state["win_streak"] = 0
    state["level"] = 0
    state["loss_streak"] = 0
    state["paused_until"] = None
    state["cycle_start"] = (started_at or datetime.now(timezone.utc)).isoformat()
    save_mm_state(state)
    return state


def mm_maybe_roll_cycle() -> dict:
    """Keep automatic signals running continuously.

    Old deployments may still have a saved 30-win rest timestamp. Clear it
    here so that legacy state cannot pause auto posting after an upgrade.
    """
    state = load_mm_state()
    if state.get("paused_until"):
        state["paused_until"] = None
        save_mm_state(state)
    return state


def signals_paused() -> bool:
    state = mm_maybe_roll_cycle()
    if state.get("manual_resume"):
        # Admin က ရပ်ထားတာကို ကိုယ်တိုင် ပြန်ဖွင့်ထားတယ် → မရပ်ပါ။
        return False
    if state.get("manual_pause"):
        return True
    return False


def pause_remaining_seconds() -> int:
    state = load_mm_state()
    until = state.get("paused_until")
    if not until:
        return 0
    try:
        delta = _parse_utc(until) - datetime.now(timezone.utc)
    except Exception:
        return 0
    return max(0, int(delta.total_seconds()))


def mm_force_resume() -> dict:
    """Admin: schedule ပြင်ပဖြစ်လည်း Pause Now နှိပ်သည်အထိ ချက်ချင်း run ပါ။"""
    state = load_mm_state()
    state = _start_new_cycle(state, datetime.now(timezone.utc))
    state["manual_pause"] = False
    state["manual_resume"] = True
    save_mm_state(state)
    return state


def mm_force_pause() -> dict:
    """Admin: စိတ်ကြိုက် ခဏရပ် (ပြန်ဖွင့်တဲ့အထိ ရပ်နေမယ်)။"""
    state = load_mm_state()
    state["manual_pause"] = True
    state["manual_resume"] = False
    save_mm_state(state)
    return state


def mm_toggle_pause() -> bool:
    """ရပ်/ဖွင့် ကို ချိန်းပါတယ်။ Return True = အခု ရပ်ထားတယ်။"""
    if signals_paused():
        mm_force_resume()
        return False
    mm_force_pause()
    return True


def mm_register_win() -> int:
    """Win → basic amount ပြန်ပြီး win count တက်သွားမယ်။ Auto post မရပ်ပါ။"""
    state = mm_maybe_roll_cycle()
    state["level"] = 0
    state["loss_streak"] = 0
    state["win_count"] = int(state.get("win_count", 0)) + 1
    state["win_streak"] = state["win_count"]
    state["paused_until"] = None
    save_mm_state(state)
    return state["win_count"]


def mm_register_loss() -> int:
    """Loss → M2 နောက်အဆင့်။ Win count က မပြောင်း (win 3 ရှုံးရင် နောက် win = 4)။"""
    state = mm_maybe_roll_cycle()
    state["level"] = min(int(state.get("level", 0)) + 1, len(M2_MULTIPLIERS) - 1)
    state["loss_streak"] = int(state.get("loss_streak", 0) or 0) + 1
    save_mm_state(state)
    return state["level"]


def mm_loss_streak() -> int:
    return int(load_mm_state().get("loss_streak", 0) or 0)


def pattern_mode_active() -> bool:
    """7 ခါ ဆက်တိုက် ရှုံးပြီး (7x) ဆိုရင် pattern mode ON။ win တာနဲ့ OFF။"""
    return mm_loss_streak() >= PATTERN_LOSS_TRIGGER


def _last_side_streak(sequence=None) -> tuple[str, int]:
    """A signal sequence ရဲ့ နောက်ဆုံး BIG/SMALL run ကိုတွက်ပါတယ်။"""
    if sequence is None:
        sequence = [
            x.get("signal")
            for x in load_source_history()
            if x.get("signal") in {"BIG", "SMALL"}
        ]
    else:
        sequence = [
            item.get("signal") if isinstance(item, dict) else item
            for item in sequence
            if (item.get("signal") if isinstance(item, dict) else item)
            in {"BIG", "SMALL"}
        ]
    seq = sequence
    if not seq:
        return ("", 0)
    last = seq[-1]
    count = 0
    for item in reversed(seq):
        if item != last:
            break
        count += 1
    return (last, count)


def _pattern_sequence(sequence=None, invert: bool = False) -> list[str]:
    """Return actual BIG/SMALL results for the recovery pattern.

    New callers pass auto_result_history, which is recorded when each
    auto-post is settled against the next game's result.  ``invert`` remains
    available only for compatibility with older direct callers; production
    pattern mode no longer guesses results by inverting bot signals.
    """
    if sequence is None:
        sequence = load_channel_config().get("auto_result_history") or []
    values = [
        item.get("signal") if isinstance(item, dict) else item
        for item in sequence
        if (item.get("signal") if isinstance(item, dict) else item)
        in {"BIG", "SMALL"}
    ]
    if invert:
        return ["SMALL" if item == "BIG" else "BIG" for item in values]
    return values


def pattern_predict(sequence=None, *, invert: bool = False) -> str | None:
    """Pattern mode rule (အသစ်):
    ကြီး ၁ခါ → ကြီး, ကြီး ၂ခါ → ကြီး, ကြီး ၃ခါ → သေး, ကြီး ၄ခါနှင့်အထက် → ကြီး
    သေး ၁ခါ → သေး, သေး ၂ခါ → သေး, သေး ၃ခါ → ကြီး, သေး ၄ခါနှင့်အထက် → သေး
    SBSB → ကြီး, BSBS → ကြီး
    """
    seq = _pattern_sequence(sequence, invert=invert)
    last, count = _last_side_streak(seq)
    if not last:
        return None
    # နောက်ဆုံး ၄ ခုက အလ alternating (SBSB / BSBS) ဆိုရင် ကြီး
    if len(seq) >= 4:
        tail4 = seq[-4:]
        if tail4 in (["SMALL", "BIG", "SMALL", "BIG"],
                     ["BIG", "SMALL", "BIG", "SMALL"]):
            return "BIG"
    if last == "BIG":
        return "SMALL" if count == 3 else "BIG"
    # SMALL side
    return "BIG" if count == 3 else "SMALL"


def load_win_stickers() -> list:
    """Admin uploaded WIN images, in upload order (WIN 1, WIN 2, ...)."""
    try:
        data = json.loads(WIN_STK_FILE.read_text()) if WIN_STK_FILE.exists() else []
        return data if isinstance(data, list) else []
    except Exception as error:
        logger.warning("Could not read win stickers: %s", error)
        return []


def save_win_stickers(items: list):
    temp = WIN_STK_FILE.with_suffix(".tmp")
    temp.write_text(json.dumps(items, indent=2))
    temp.replace(WIN_STK_FILE)


def add_win_sticker(file_id: str) -> int:
    items = load_win_stickers()
    if file_id not in items:
        items.append(file_id)
        save_win_stickers(items)
    return len([item for item in items if isinstance(item, str)])


def add_win_photo(file_id: str, caption: str = "") -> int:
    """Signal မပို့ခင်တင်မယ့် ပုံ+စာကို WIN stickers နဲ့ သီးခြားသိမ်းပါတယ်။"""
    entry = {"photo": file_id, "caption": caption or ""}
    temp = AUTO_INTRO_FILE.with_suffix(".tmp")
    temp.write_text(json.dumps(entry, indent=2))
    temp.replace(AUTO_INTRO_FILE)

    # Previous version stored this photo inside win_stickers.json. Remove all
    # such entries so the first real sticker remains WIN 1.
    stickers = [item for item in load_win_stickers() if isinstance(item, str)]
    save_win_stickers(stickers)
    return 1


def intro_photo_item() -> dict | None:
    """Auto post signal မပို့ခင် အရင်တင်ပေးမယ့် သီးခြားပုံ+စာ။"""
    try:
        if AUTO_INTRO_FILE.exists():
            item = json.loads(AUTO_INTRO_FILE.read_text())
            if isinstance(item, dict) and item.get("photo"):
                return item
    except Exception as error:
        logger.warning("Could not read auto intro: %s", error)

    # Backward compatibility for a photo saved by the previous version.
    for item in load_win_stickers():
        if isinstance(item, dict) and item.get("photo"):
            return item
    return None


def sticker_for_streak(streak: int) -> str | None:
    """WIN 1..N stickers — win number အတိုင်း (မရှိရင် နောက်ဆုံးတစ်ခု)။"""
    items = [x for x in load_win_stickers() if isinstance(x, str)]
    if not items or streak < 1:
        return None
    return items[min(streak, len(items)) - 1]


def enabled_channels(config: dict) -> list:
    return [
        (chat_id, item)
        for chat_id, item in (config.get("channels") or {}).items()
        if isinstance(item, dict) and item.get("enabled", True)
    ]


def normalize_channel_target(value: str) -> str:
    """Normalize the common formats users copy for private channels.

    Telegram's Bot API expects channel/supergroup IDs in the ``-100...``
    format.  Some ID bots and copied screenshots omit the leading minus sign.
    Also accept a private message link such as ``t.me/c/1234567890/42``.
    Invite links (``t.me/+...``) cannot be resolved by the Bot API, so those
    are deliberately left unchanged and the caller can show the forward
    message alternative.
    """
    target = (value or "").strip()
    target = target.rstrip("/")

    private_link = re.search(
        r"(?:https?://)?(?:t\.me|telegram\.me)/c/(\d+)(?:/\d+)?$",
        target,
        flags=re.IGNORECASE,
    )
    if private_link:
        return f"-100{private_link.group(1)}"

    public_link = re.search(
        r"(?:https?://)?(?:t\.me|telegram\.me)/([A-Za-z_][A-Za-z0-9_]{3,})$",
        target,
        flags=re.IGNORECASE,
    )
    if public_link:
        return f"@{public_link.group(1)}"

    # An ID copied from an ID bot may be displayed as 100xxxxxxxxxx without
    # the minus sign.  Convert only the channel-style 100... form; do not
    # turn ordinary positive user IDs into chat IDs.
    if re.fullmatch(r"100\d+", target):
        return f"-{target}"
    return target


def forwarded_chat(message):
    """Return the channel/group Chat from a forwarded Telegram message.

    PTB 20+ exposes this as Message.forward_origin.  The older
    forward_from_chat field is kept as a fallback for older deployments.
    """
    if not message:
        return None
    origin = getattr(message, "forward_origin", None)
    chat = getattr(origin, "chat", None)
    if chat is not None:
        return chat
    return getattr(message, "forward_from_chat", None)


def build_signal_text(transaction: str, signal: str, amount: int) -> str:
    """Text-only signal, e.g. `TRX 92 S 7000`."""
    tail = re.sub(r"\D", "", str(transaction))[-2:] or str(transaction)[-2:]
    side = "B" if signal == "BIG" else "S"
    return f"TRX {tail} {side} {amount}"


def _next_signal_mode() -> str:
    """Return the current mode and persist the opposite mode for next time."""
    try:
        state = json.loads(TURN_STATE_FILE.read_text()) if TURN_STATE_FILE.exists() else {}
    except Exception:
        state = {}
    # ပုံမှန် flow: ဒဲ့ (source) တစ်ခါ → ကန့် (reverse) တစ်ခါ ... ဆက်တိုက်။
    # win/loss ဘယ်လိုဖြစ်ဖြစ် ဒီအလှည့်ကို reset မလုပ်ပါ။
    mode = state.get("next_mode", "source")
    if mode not in {"reverse", "source"}:
        mode = "source"
    temp = TURN_STATE_FILE.with_suffix(".tmp")
    temp.write_text(json.dumps({"next_mode": "source" if mode == "reverse" else "reverse"}))
    temp.replace(TURN_STATE_FILE)
    return mode


def _next_auto_signal_mode(config: dict) -> str:
    """Consume the auto-post turn without letting manual signals change it.

    Normal recovery always alternates source/direct → reverse → source/direct.
    Pattern signals do not consume this turn, so after pattern mode wins the
    normal flow resumes opposite the last normal signal that was sent.
    """
    mode = config.get("auto_next_mode", "source")
    if mode not in {"reverse", "source"}:
        mode = "source"
    config["auto_next_mode"] = "source" if mode == "reverse" else "reverse"
    return mode


def _apply_signal_mode(source_signal: str) -> str:
    mode = _next_signal_mode()
    return (
        ("SMALL" if source_signal == "BIG" else "BIG")
        if mode == "reverse"
        else source_signal
    )


def load_user_rounds() -> dict:
    try:
        data = json.loads(USER_ROUNDS_FILE.read_text()) if USER_ROUNDS_FILE.exists() else {}
        return data if isinstance(data, dict) else {}
    except Exception as e:
        logger.warning("Could not read user round history: %s", e)
        return {}


def save_user_rounds(data: dict):
    temp = USER_ROUNDS_FILE.with_suffix(".tmp")
    temp.write_text(json.dumps(data, indent=2, ensure_ascii=False))
    temp.replace(USER_ROUNDS_FILE)


def _user_rounds(user_id: int) -> list:
    data = load_user_rounds()
    rounds = data.get(str(user_id), [])
    return rounds if isinstance(rounds, list) else []


def save_user_round(
    user_id: int,
    txn_no: str,
    signal: str,
    badge: str,
    confidence: int,
    issued_at: datetime,
    round_end: datetime,
) -> str:
    """Persist a prediction before sending it so results survive restarts."""
    round_id = issued_at.strftime("%Y%m%d%H%M%S%f")
    data = load_user_rounds()
    rounds = data.setdefault(str(user_id), [])
    rounds.append({
        "id": round_id,
        "transaction": txn_no,
        "signal": signal,
        "badge": badge,
        "confidence": confidence,
        "issued_at": issued_at.isoformat(),
        "round_end": round_end.isoformat(),
        "status": "OPEN",
        "result": None,
        "actual": None,
        "settled_at": None,
        "settled_by": None,
        "message_id": None,
        "chat_id": user_id,
    })
    data[str(user_id)] = rounds[-100:]
    save_user_rounds(data)
    return round_id


def update_user_round(user_id: int, round_id: str, **changes) -> dict | None:
    data = load_user_rounds()
    rounds = data.get(str(user_id), [])
    for item in rounds:
        if item.get("id") == round_id:
            item.update(changes)
            save_user_rounds(data)
            return item
    return None


def get_user_round(user_id: int, round_id: str) -> dict | None:
    for item in _user_rounds(user_id):
        if item.get("id") == round_id:
            return item
    return None


def open_rounds(user_id: int) -> list:
    now = datetime.now(timezone.utc)
    return [
        item for item in _user_rounds(user_id)
        if item.get("status") == "OPEN"
        and _parse_utc(item.get("round_end")) > now
    ]


def _parse_utc(value: str | None) -> datetime:
    try:
        parsed = datetime.fromisoformat(value or "")
        return parsed if parsed.tzinfo else parsed.replace(tzinfo=timezone.utc)
    except (TypeError, ValueError):
        return datetime.min.replace(tzinfo=timezone.utc)


def user_stats(user_id: int) -> tuple[int, int, int, float]:
    rounds = _user_rounds(user_id)
    wins = sum(1 for item in rounds if item.get("result") == "WIN")
    losses = sum(1 for item in rounds if item.get("result") == "LOSS")
    total = wins + losses
    rate = (wins / total * 100) if total else 0.0
    return wins, losses, total, rate


def result_from_value(value) -> tuple[str | None, str | None]:
    """Convert common lottery API result shapes to BIG/SMALL."""
    if value is None:
        return None, None
    if isinstance(value, bool):
        return None, None
    if isinstance(value, (int, float)) or (
        isinstance(value, str) and re.fullmatch(r"\d+", value.strip())
    ):
        number = int(value)
        if 0 <= number <= 9:
            return ("BIG" if number >= 5 else "SMALL"), str(number)
        return None, str(number)
    text = str(value).upper()
    if re.search(r"\bBIG\b", text):
        return "BIG", None
    if re.search(r"\bSMALL\b", text):
        return "SMALL", None
    return None, None


def _walk_result_records(value):
    """Yield dictionaries from nested JSON returned by different game sites."""
    if isinstance(value, dict):
        yield value
        for child in value.values():
            yield from _walk_result_records(child)
    elif isinstance(value, list):
        for child in value:
            yield from _walk_result_records(child)


def _result_for_transaction(payload, txn_no: str) -> tuple[str | None, str | None]:
    txn = str(txn_no).strip()
    for item in _walk_result_records(payload):
        identifiers = " ".join(
            str(item.get(key, "")) for key in (
                "transaction", "transactionNo", "transaction_no",
                "period", "issue", "issueNumber", "round", "roundNo",
                "id", "gameId",
            )
        )
        if txn not in identifiers:
            continue
        for key in ("result", "number", "num", "openNumber", "winningNumber", "value", "code"):
            if key in item:
                direction, actual = result_from_value(item[key])
                if direction:
                    return direction, actual
        direction, actual = result_from_value(item)
        if direction:
            return direction, actual
    return None, None


async def fetch_game_result(txn_no: str) -> tuple[str | None, str | None]:
    """Best-effort result lookup; unavailable endpoints never create a result."""
    if not GAME_HISTORY_URL:
        return None, None
    url = GAME_HISTORY_URL.replace("{txn}", quote(str(txn_no), safe=""))
    params = {} if "{txn}" in GAME_HISTORY_URL else {
        "txn": txn_no,
        "transactionNo": txn_no,
        "period": txn_no,
        "issue": txn_no,
    }
    try:
        async with httpx.AsyncClient(
            timeout=CHANNEL_FETCH_TIMEOUT_SECONDS,
            follow_redirects=True,
            headers={"User-Agent": "DrThetPyinnSignalBot/2.0"},
        ) as client:
            response = await client.get(url, params=params)
            response.raise_for_status()
            try:
                payload = response.json()
            except ValueError:
                payload = response.text
        return _result_for_transaction(payload, txn_no)
    except (httpx.HTTPError, OSError) as error:
        logger.warning("Could not read game result for %s: %s", txn_no, error)
        return None, None


def signal_quality(signal: str) -> tuple[str, int]:
    """Give a transparent confidence label from available history only."""
    source = [x.get("signal") for x in load_source_history()[-12:] if x.get("signal") in {"BIG", "SMALL"}]
    predicted = [x for x in load_signal_history()[-12:] if x.get("signal") in {"BIG", "SMALL"}]
    confidence = 50
    if len(source) >= 3:
        same = sum(1 for item in source[-3:] if item == source[-1])
        confidence += same * 4
    if predicted:
        settled = [x for x in predicted if x.get("result") in {"WIN", "LOSS"}]
        if settled:
            wins = sum(1 for x in settled if x.get("result") == "WIN")
            confidence += round((wins / len(settled) - 0.5) * 20)
    confidence = max(50, min(78, confidence))
    badge = "Strong" if confidence >= 68 else "Medium" if confidence >= 58 else "Weak"
    return badge, confidence


def format_countdown(seconds: int) -> str:
    seconds = max(0, int(seconds))
    return f"{seconds // 60:02d}:{seconds % 60:02d}"


def stats_text(user_id: int) -> str:
    wins, losses, total, rate = user_stats(user_id)
    open_count = len(open_rounds(user_id))
    return (
        "📈 *My Signal Record*\n"
        "━━━━━━━━━━━━━━━━━━━━\n"
        f"✅ WIN       : {wins}\n"
        f"❌ LOSS      : {losses}\n"
        f"🎮 Completed : {total}\n"
        f"🏆 Win rate  : {rate:.1f}%\n"
        f"⏳ Active    : {open_count}\n\n"
        "Win rate သည် သင်မှတ်တမ်းတင်ထားသော result များကိုသာ အခြေခံထားပါသည်။"
    )


def parse_transaction_from_text(text: str) -> str | None:
    cleaned = unescape(re.sub(r"<[^>]+>", " ", text or ""))
    match = re.search(
        r"(?:TRANSACTION(?:\s+NO\.?)?|TXN|ROUND(?:\s+ID)?|PERIOD|ISSUE)"
        r"\s*[:#-]?\s*(\d{8,})",
        cleaned,
        flags=re.IGNORECASE,
    )
    if match:
        return match.group(1)
    # Some source channels put the transaction number on its own line,
    # without a "Transaction" label. Prefer a long standalone number so a
    # date, confidence percentage, or result number is not selected.
    standalone = re.findall(r"(?<!\d)(\d{12,})(?!\d)", cleaned)
    return max(standalone, key=len) if standalone else None


def parse_result_from_text(text: str) -> tuple[str | None, str | None]:
    """Only parse an outcome when the post explicitly labels it as a result."""
    cleaned = unescape(re.sub(r"<[^>]+>", " ", text or ""))
    match = re.search(
        r"(?:RESULT|OPEN(?:ING)?\s+NUMBER|WINNING\s+NUMBER|ACTUAL)"
        r"\s*[:#-]?\s*(BIG|SMALL|\d+)",
        cleaned,
        flags=re.IGNORECASE,
    )
    return result_from_value(match.group(1)) if match else (None, None)


async def settle_channel_result(bot, transaction: str, direction: str, actual: str | None):
    """Settle every user's open prediction for an explicitly labelled result post."""
    for user_id, rounds in load_user_rounds().items():
        for item in rounds if isinstance(rounds, list) else []:
            if (
                item.get("status") == "OPEN"
                and str(item.get("transaction", "")).strip() == str(transaction).strip()
            ):
                result = "WIN" if item.get("signal") == direction else "LOSS"
                updated = update_user_round(
                    int(user_id),
                    item.get("id", ""),
                    status=result,
                    result=result,
                    actual=actual or direction,
                    settled_at=datetime.now(timezone.utc).isoformat(),
                    settled_by="telegram_source",
                )
                settle_signal_history(item.get("id", ""), result, actual or direction)
                if updated and updated.get("message_id"):
                    try:
                        await bot.edit_message_caption(
                            chat_id=updated.get("chat_id", int(user_id)),
                            message_id=updated["message_id"],
                            caption=build_round_caption(updated),
                            parse_mode=ParseMode.MARKDOWN,
                            reply_markup=kb_signal_actions(),
                        )
                    except Exception as error:
                        logger.warning("Could not show channel-settled result: %s", error)


def build_round_caption(item: dict, remaining: int | None = None) -> str:
    signal = item.get("signal", "—")
    signal_txt = "🔴 BIG" if signal == "BIG" else "🔵 SMALL"
    return (
        "🎯 *Signal Result*\n"
        "━━━━━━━━━━━━━━━━━━━━\n"
        f"🎮 Transaction no. : `{item.get('transaction', '—')}`\n"
        f"🕐 Time             : {item.get('issued_at', '')[:19].replace('T', ' ')} UTC\n"
        "━━━━━━━━━━━━━━━━━━━━\n"
        f"📊 Direction        : *{signal_txt}*\n"
        f"🏷 Status           : *{item.get('badge', 'Weak')}*\n"
        f"🎯 Confidence       : *{item.get('confidence', 50)}%*"
    )


async def settle_round_now(
    bot,
    user_id: int,
    round_id: str,
    chat_id: int,
    *,
    announce_pending: bool = True,
) -> dict | None:
    item = get_user_round(user_id, round_id)
    if not item or item.get("result") in {"WIN", "LOSS"}:
        return item
    direction, actual = await fetch_game_result(item.get("transaction", ""))
    if not direction:
        return item
    result = "WIN" if direction == item.get("signal") else "LOSS"
    updated = update_user_round(
        user_id,
        round_id,
        status=result,
        result=result,
        actual=actual or direction,
        settled_at=datetime.now(timezone.utc).isoformat(),
        settled_by="game_history",
    )
    settle_signal_history(round_id, result, actual or direction)
    if updated:
        message_id = updated.get("message_id")
        if message_id:
            try:
                await bot.edit_message_caption(
                    chat_id=chat_id,
                    message_id=message_id,
                    caption=build_round_caption(updated),
                    parse_mode=ParseMode.MARKDOWN,
                    reply_markup=kb_signal_actions(round_id),
                )
            except Exception as error:
                logger.warning("Could not update settled signal message: %s", error)
    return updated


async def track_round(bot, user_id: int, round_id: str, chat_id: int):
    """Keep the Telegram signal message in sync with the 1-minute round."""
    item = get_user_round(user_id, round_id)
    if not item:
        return
    message_id = item.get("message_id")
    if not message_id:
        return
    end_at = _parse_utc(item.get("round_end"))
    while True:
        item = get_user_round(user_id, round_id)
        if not item or item.get("result") in {"WIN", "LOSS"}:
            return
        remaining = int((end_at - datetime.now(timezone.utc)).total_seconds() + 0.999)
        if remaining <= 0:
            break
        try:
            await bot.edit_message_caption(
                chat_id=chat_id,
                message_id=message_id,
                caption=build_round_caption(item, remaining),
                parse_mode=ParseMode.MARKDOWN,
                reply_markup=kb_signal_actions(round_id),
            )
        except RetryAfter as error:
            await asyncio.sleep(min(max(1, int(error.retry_after)), 10))
        except Exception as error:
            logger.warning("Live countdown update failed: %s", error)
            await asyncio.sleep(2)
        else:
            await asyncio.sleep(COUNTDOWN_UPDATE_SECONDS)
    await asyncio.sleep(RESULT_GRACE_SECONDS)
    await settle_round_now(bot, user_id, round_id, chat_id, announce_pending=True)

def parse_signal_from_text(text: str) -> str | None:
    cleaned = unescape(re.sub(r"<[^>]+>", " ", text)).upper()
    matches = re.findall(r"\b(BIG|SMALL)\b", cleaned)
    if matches:
        return matches[-1]
    return None

def parse_signal_and_level_from_text(text: str) -> tuple[str | None, int | None]:
    """Source channel posts e.g. 'BIG (1)' / 'SMALL (3)'. The number in the
    parentheses is the M2 ladder level for THIS signal (1 = basic amount),
    and it doubles as the win/loss tell for the PREVIOUS signal:
      - level == 1  → previous signal WON (ladder reset)
      - level > 1   → previous signal LOST (ladder moved up)
    """
    cleaned = unescape(re.sub(r"<[^>]+>", " ", text)).upper()
    matches = re.findall(r"\b(BIG|SMALL)\b\s*\(\s*(\d+)\s*\)", cleaned)
    if matches:
        direction, level = matches[-1]
        return direction, int(level)
    # Fall back to a bare BIG/SMALL with no level tag.
    return parse_signal_from_text(text), None

def _parse_public_channel_posts(page: str) -> list[tuple[datetime, str, str | None, int | None]]:
    """Extract signal text and its public post time from t.me/s HTML."""
    texts = re.findall(
        r'<div class="tgme_widget_message_text js-message_text"[^>]*>(.*?)</div>',
        page,
        flags=re.IGNORECASE | re.DOTALL,
    )
    times = re.findall(r'<time datetime="([^"]+)"', page, flags=re.IGNORECASE)
    posts: list[tuple[datetime, str, str | None, int | None]] = []
    for raw_text, raw_time in zip(texts, times):
        signal, level = parse_signal_and_level_from_text(raw_text)
        if not signal:
            continue
        try:
            post_time = datetime.fromisoformat(raw_time.replace("Z", "+00:00"))
        except ValueError:
            continue
        if post_time.tzinfo is None:
            post_time = post_time.replace(tzinfo=timezone.utc)
        posts.append((
            post_time.astimezone(timezone.utc),
            signal,
            parse_transaction_from_text(raw_text),
            level,
        ))
    return posts

async def fetch_latest_public_channel_signal() -> str | None:
    """Read the latest signal from the public channel preview; no admin rights required."""
    # A stale/incorrect SIGNAL_CHANNEL_URL variable should not disable the
    # bot when the configured SIGNAL_CHANNEL name is still valid.
    default_url = f"https://t.me/s/{SIGNAL_CHANNEL.lstrip('@').strip('/')}"
    urls = []
    for url in (SIGNAL_CHANNEL_URL, default_url):
        clean_url = str(url or "").strip()
        if clean_url and clean_url not in urls:
            urls.append(clean_url)

    last_error = None
    for source_url in urls:
        try:
            async with httpx.AsyncClient(
                timeout=CHANNEL_FETCH_TIMEOUT_SECONDS,
                follow_redirects=True,
                headers={"User-Agent": "Mozilla/5.0 signal-bot-public-reader"},
            ) as client:
                response = await client.get(source_url)
                response.raise_for_status()
            posts = _parse_public_channel_posts(response.text)
            if not posts:
                logger.warning("No BIG/SMALL signal found at %s", source_url)
                continue
            post_time, source_signal, source_transaction, source_level = max(
                posts, key=lambda item: item[0]
            )
            age_minutes = (datetime.now(timezone.utc) - post_time).total_seconds() / 60
            if age_minutes > CHANNEL_SIG_MAX_AGE_MIN:
                logger.warning(
                    "Latest public channel signal is stale: %.1f minutes old",
                    age_minutes,
                )
                continue
            save_channel_signal(
                source_signal,
                source_timestamp=post_time.isoformat(),
                source_transaction=source_transaction,
                source_level=source_level,
            )
            logger.info(
                "Public channel signal read from %s: %s at %s",
                source_url,
                source_signal,
                post_time.isoformat(),
            )
            return source_signal
        except (httpx.HTTPError, OSError, ValueError) as error:
            last_error = error
            logger.warning("Could not read public channel preview %s: %s", source_url, error)

    # A short network hiccup should not make manual Get Signal fail if the
    # source was successfully read recently.  Auto-post still uses the fresh
    # fetch above and therefore never posts an old cached signal.
    cached = get_channel_signal(CHANNEL_SIG_MAX_AGE_MIN)
    if cached:
        logger.warning("Using recent cached source signal after public fetch failure")
        return cached
    if last_error:
        logger.warning("No usable public source signal: %s", last_error)
    return None

# ── Signal history / anti-streak ───────────────────────────────────────────────

def load_signal_history() -> list:
    if SIGNAL_HIST_FILE.exists():
        try:
            return json.loads(SIGNAL_HIST_FILE.read_text())
        except Exception:
            pass
    return []

def save_signal_to_history(
    signal: str,
    txn_no: str | None = None,
    prediction_id: str | None = None,
):
    hist = load_signal_history()
    hist.append({
        "signal": signal,
        "transaction": txn_no,
        "prediction_id": prediction_id,
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "result": None,
    })
    temp = SIGNAL_HIST_FILE.with_suffix(".tmp")
    temp.write_text(json.dumps(hist[-20:], indent=2))
    temp.replace(SIGNAL_HIST_FILE)


def settle_signal_history(prediction_id: str, result: str, actual: str | None):
    hist = load_signal_history()
    for item in reversed(hist):
        if item.get("prediction_id") == prediction_id:
            item["result"] = result
            item["actual"] = actual
            item["settled_at"] = datetime.now(timezone.utc).isoformat()
            temp = SIGNAL_HIST_FILE.with_suffix(".tmp")
            temp.write_text(json.dumps(hist[-20:], indent=2))
            temp.replace(SIGNAL_HIST_FILE)
            return

def get_recent_streak() -> tuple[str, int]:
    hist = load_signal_history()
    if not hist:
        return ("", 0)
    last   = hist[-1]["signal"]
    streak = sum(1 for e in reversed(hist) if e["signal"] == last)
    return (last, streak)

# ── Core signal generator ──────────────────────────────────────────────────────

async def generate_signal(txn_no: str) -> str | None:
    """Return alternating reverse/source signals from the latest source signal.

    There is intentionally no random or hash fallback. A missing source signal
    must never become a fabricated trading direction.
    """
    del txn_no
    ch_sig = await fetch_latest_public_channel_signal()
    if not ch_sig:
        logger.warning("Signal unavailable because source signal is unavailable")
        return None
    # Channel auto-post နဲ့ တူညီအောင် — 3x ရှုံးနေချိန် (pattern mode) မှာ
    # တောင်းလို့ရတဲ့ signal ကိုပါ pattern rule နဲ့ ပေးပါတယ်။
    if pattern_mode_active():
        result_history = load_channel_config().get("auto_result_history") or None
        pattern_output = pattern_predict(result_history)
        if pattern_output:
            logger.info("Manual pattern mode (%s loss streak) → %s", mm_loss_streak(), pattern_output)
            return pattern_output
    # The turn is independent from signal history and survives restarts.
    # This guarantees: reverse, source, reverse, source ... even when the
    # source repeats BIG (or repeats SMALL).
    mode = _next_signal_mode()
    signal = ("SMALL" if ch_sig == "BIG" else "BIG") if mode == "reverse" else ch_sig
    logger.info("Public channel %s turn: %s → %s", mode, ch_sig, signal)
    return signal

def increment_txn_no(txn_no: str) -> str:
    txn_no = txn_no.strip()
    i = len(txn_no)
    while i > 0 and txn_no[i - 1].isdigit():
        i -= 1
    prefix = txn_no[:i]
    suffix = txn_no[i:]
    if suffix:
        return prefix + str(int(suffix) + 1).zfill(len(suffix))
    return txn_no + "2"

