async def auto_post_job(context: ContextTypes.DEFAULT_TYPE):
    """Poll the configured public source and publish each new source post once."""
    config = load_channel_config()
    if not config.get("auto_post") or not config.get("channels"):
        return

    # Auto post runs 24/7. Only an explicit admin Pause Now can stop it.
    if signals_paused():
        return

    source_signal = await fetch_latest_public_channel_signal()
    if not source_signal or not CHANNEL_SIG_FILE.exists():
        return
    try:
        source_data = json.loads(CHANNEL_SIG_FILE.read_text())
    except Exception:
        return
    source_timestamp = source_data.get("timestamp")
    if not source_timestamp or source_timestamp == config.get("last_source_timestamp"):
        return

    targets = enabled_channels(config)
    if not targets:
        return

    channel_level = source_data.get("source_level")
    if not channel_level:
        logger.warning("Channel post had no (N) level tag; win/loss for the pending signal will be checked next time")

    # Settle the previous pending signal using THIS post's (N) label —
    # accounting for whichever mode (source/reverse) that pending signal
    # was actually posted in.
    await _settle_auto_pending(context.bot, config, channel_level)
    config = load_channel_config()
    # A missing result must never halt auto posting indefinitely. Once a newer
    # source post exists, discard the unresolved prior pending record without
    # changing win/loss or pattern state, then continue with the new signal.
    if config.get("auto_pending"):
        logger.warning(
            "Previous auto result is unavailable; clearing pending signal so 24/7 posting continues"
        )
        config["auto_pending"] = None
        save_channel_config(config)

    if signals_paused():
        return

    # 3 ခါ ဆက်တိုက် ရှုံးရင် (3x) ပုံမှန် reverse/source turn ကို ခဏပြောင်းပြီး
    # bot ထုတ်ထားတဲ့ signal sequence အပေါ် pattern rule နဲ့ ပေးပါတယ်။
    # တစ်ခါ win တာနဲ့ နဂို turn ကို ပြန်သွားပါတယ်။
    result_history = config.get("auto_result_history") or None
    pattern_output = (
        pattern_predict(result_history)
        if pattern_mode_active() else None
    )
    if pattern_output:
        output = pattern_output
        mode = "source" if output == source_signal else "reverse"
        logger.info("Pattern mode (%s loss streak) → %s", mm_loss_streak(), output)
    else:
        # Consume one AUTO turn only for a genuinely new source post.
        # Manual VIP requests use their own turn and cannot disturb D → R → D.
        mode = _next_auto_signal_mode(config)
        output = (
            ("SMALL" if source_signal == "BIG" else "BIG")
            if mode == "reverse" else source_signal
        )
    transaction = str(source_data.get("source_transaction") or "").strip() or "—"
    amount = current_bet()
    text = build_signal_text(transaction, output, amount)

    config["last_source_timestamp"] = source_timestamp
    config["auto_pending"] = {
        "transaction": transaction,
        "signal": output,
        "source_signal": source_signal,
        "mode": mode,
        "amount": amount,
        "sent_at": datetime.now(timezone.utc).isoformat(),
    }
    signal_history = [
        item
        for item in (config.get("auto_signal_history") or [])
        if isinstance(item, str) and item in {"BIG", "SMALL"}
    ]
    signal_history.append(output)
    config["auto_signal_history"] = signal_history[-30:]
    save_channel_config(config)

    if not config.get("auto_intro_sent"):
        await _send_auto_intro(context.bot, targets)
        config["auto_intro_sent"] = True
        save_channel_config(config)

    for chat_id, _item in targets:
        try:
            await _send_text_retry(context.bot, int(chat_id), text)
        except Exception as error:
            logger.warning("Auto post failed for %s: %s", chat_id, error)


async def auto_post_loop(app: Application):
    while True:
        try:
            await auto_post_job(type("JobContext", (), {"bot": app.bot})())
        except asyncio.CancelledError:
            raise
        except Exception:
            logger.exception("Auto-post loop error")
        await asyncio.sleep(15)

