async def _save_channel_chat(update: Update, ctx: ContextTypes.DEFAULT_TYPE, chat):
    """Validate bot permissions and save a resolved Telegram chat."""
    ctx.user_data["state"] = None
    if chat is None:
        await update.message.reply_text(
            "❌ Channel/group ကို မတွေ့ပါ။\n"
            "Bot ကို အဲဒီ channel/group ထဲ ထည့်ပြီး Admin ခန့်ထားပါ။"
        )
        return
    try:
        me = await ctx.bot.get_me()
        member = await ctx.bot.get_chat_member(chat.id, me.id)
        if member.status not in {"administrator", "creator"}:
            await update.message.reply_text(
                "❌ Bot ကို အဲဒီ channel/group မှာ Admin ခန့်ထားပြီးမှ ပြန်စမ်းပါ။"
            )
            return
        config = load_channel_config()
        config.setdefault("channels", {})[str(chat.id)] = {
            "title": chat.title or chat.username or str(chat.id),
            "username": chat.username,
            "type": chat.type,
            "enabled": True,
        }
        save_channel_config(config)
        await update.message.reply_text(
            f"✅ *Channel Added*\n\n"
            f"📍 {chat.title or chat.username or chat.id}\n"
            f"📣 Auto Post: {'ON' if config.get('auto_post') else 'OFF'}",
            parse_mode=ParseMode.MARKDOWN,
            reply_markup=kb_admin(),
        )
    except Exception as error:
        logger.warning("Could not add auto-post destination %s: %s", chat.id, error)
        await update.message.reply_text(
            "❌ Channel/group ကို မတွေ့ပါ။ Bot ထည့်ပြီး Admin ခန့်ထားခြင်း၊ "
            "ပြီးတော့ Bot ကို Admin ခန့်ထားပြီးသားဖြစ်ကြောင်း စစ်ပါ။"
        )


async def _do_add_channel(update: Update, ctx: ContextTypes.DEFAULT_TYPE, text: str):
    target = normalize_channel_target(text)
    if not target:
        ctx.user_data["state"] = "admin_add_channel"
        await update.message.reply_text(
            "❌ `@username` သို့မဟုတ် chat ID (`-100...`) ပေးပါ။\n"
            "Private channel ဖြစ်ရင် channel post တစ်ခုကို ဒီ bot ဆီ "
            "*Forward* လုပ်ပို့နိုင်ပါတယ်။",
            parse_mode=ParseMode.MARKDOWN,
        )
        return
    try:
        chat = await ctx.bot.get_chat(target)
    except Exception as error:
        logger.warning("Could not resolve auto-post destination %s: %s", target, error)
        ctx.user_data["state"] = "admin_add_channel"
        await update.message.reply_text(
            "❌ ဒီ ID/link နဲ့ channel ကို မတွေ့ပါ။\n\n"
            "Private channel အတွက်:\n"
            "1) Bot ကို channel ထဲထည့်ပြီး Admin ခန့်ပါ\n"
            "2) Channel ထဲက post တစ်ခုကို ဒီ bot chat ထဲ *Forward* လုပ်ပါ\n"
            "3) မရရင် `-100...` ပုံစံ ID ကို ပေးပါ\n\n"
            "⚠️ `t.me/+invite-link` ကို Bot API ကနေ တိုက်ရိုက်ရှာလို့မရပါ။",
            parse_mode=ParseMode.MARKDOWN,
        )
        return
    await _save_channel_chat(update, ctx, chat)


async def _do_add_forwarded_channel(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Add the channel/group identified by an admin's forwarded post."""
    chat = forwarded_chat(update.message)
    if chat is None:
        return False
    chat_type = getattr(chat, "type", "")
    if chat_type not in {"channel", "group", "supergroup"}:
        return False
    await _save_channel_chat(update, ctx, chat)
    return True

async def _do_add_vip(update: Update, ctx: ContextTypes.DEFAULT_TYPE, text: str):
    """Add / extend a VIP member manually.

    Accepts flexible input, e.g.:
        123456789 30
        123456789,30
        123456789 30 days
        123456789   30d
        123456789          (days မထည့်ရင် lifetime)
    """
    ctx.user_data["state"] = None
    raw = (text or "").replace(",", " ").replace("\n", " ").strip()
    parts = [p for p in raw.split() if p.strip()]
    if not parts:
        await update.message.reply_text(
            "❌ Format: `USER_ID DAYS`\nExample: `123456789 30`",
            parse_mode=ParseMode.MARKDOWN,
        )
        return

    def _digits(value: str) -> str:
        return "".join(ch for ch in value if ch.isdigit())

    uid_raw = _digits(parts[0])
    if not uid_raw:
        await update.message.reply_text("❌ User ID က ဂဏန်းဖြစ်ရပါမည်\nExample: `123456789 30`",
                                        parse_mode=ParseMode.MARKDOWN)
        return

    days = 0
    if len(parts) > 1:
        day_raw = ""
        for token in parts[1:]:
            day_raw = _digits(token)
            if day_raw:
                break
        if not day_raw:
            await update.message.reply_text("❌ DAYS က ဂဏန်းဖြစ်ရပါမည် (0 = Lifetime)")
            return
        try:
            days = int(day_raw)
        except ValueError:
            await update.message.reply_text("❌ DAYS က ဂဏန်းဖြစ်ရပါမည် (0 = Lifetime)")
            return
        if days < 0 or days > 36500:
            await update.message.reply_text("❌ DAYS က 0 မှ 36500 အတွင်း ဖြစ်ရပါမည်")
            return

    uid = str(int(uid_raw))
    vip = load_vip()
    existing = vip.get(uid) if isinstance(vip.get(uid), dict) else {}

    if days == 0:
        expiry = None
    else:
        # Extend an active membership instead of shortening it.
        start = datetime.now(timezone.utc)
        old_expiry = existing.get("expiry") if existing else None
        if old_expiry:
            try:
                old_dt = datetime.fromisoformat(old_expiry)
                if old_dt.tzinfo is None:
                    old_dt = old_dt.replace(tzinfo=timezone.utc)
                if old_dt > start:
                    start = old_dt
            except Exception:
                pass
        expiry = (start + timedelta(days=days)).isoformat()

    expiry_str = "♾ Lifetime" if expiry is None else expiry[:10]
    try:
        chat = await ctx.bot.get_chat(int(uid))
        first_name = chat.first_name or ""; username = chat.username or ""
    except Exception:
        first_name = (existing.get("first_name") if existing else "") or "Unknown"
        username = (existing.get("username") if existing else "") or ""

    vip[uid] = {"first_name": first_name, "username": username, "expiry": expiry,
                "added_by": update.effective_user.id, "added_at": datetime.now(timezone.utc).isoformat()}
    try:
        save_vip(vip)
    except Exception as e:
        logger.exception("Could not save VIP data: %s", e)
        await update.message.reply_text(f"❌ VIP သိမ်းဆည်းမရပါ: {e}")
        return

    if not is_vip(int(uid)):
        await update.message.reply_text("❌ VIP ထည့်တာ မအောင်မြင်ပါ။ ထပ်စမ်းပါ။")
        return

    await update.message.reply_text(
        f"✅ *VIP Added!*\n\n👤 ID: `{uid}`\n📛 Name: {first_name}\n"
        f"📅 Days: {'Lifetime' if days == 0 else days}\n📅 Expiry: {expiry_str}",
        parse_mode=ParseMode.MARKDOWN,
    )
    try:
        await _send_photo_retry(
            ctx.bot,
            int(uid),
            "vip_welcome",
            caption=(f"🎉 *ကြိုဆိုပါတယ် {first_name}!*\n\n👑 သင်သည် *VIP Member* ဖြစ်သွားပါပြီ!\n"
                     f"━━━━━━━━━━━━━━━━━━━━\n📅 သက်တမ်း : {expiry_str}\n\n🎯 */start* နှိပ်၍ Signals ရယူပါ!"),
            parse_mode=ParseMode.MARKDOWN,
        )
    except Exception as e:
        logger.warning(f"Could not notify VIP {uid}: {e}")

async def _do_grant_free(update: Update, ctx: ContextTypes.DEFAULT_TYPE, text: str):
    ctx.user_data["state"] = None
    try:
        uid = str(int(text.strip()))
    except ValueError:
        await update.message.reply_text("❌ User ID က ဂဏန်းဖြစ်ရပါမည်")
        return

    data = load_free_access()
    existing = data.get(uid)
    today = _today_key()
    if not isinstance(existing, dict) or existing.get("date") != today:
        data[uid] = {
            "enabled": True,
            "date": today,
            "used_seconds": 0,
            "active": False,
            "started_at": None,
            "granted_by": update.effective_user.id,
            "granted_at": datetime.now(timezone.utc).isoformat(),
        }
    else:
        existing["enabled"] = True
        existing["granted_by"] = update.effective_user.id
        existing["granted_at"] = datetime.now(timezone.utc).isoformat()
    save_free_access(data)

    remaining = free_remaining_seconds(int(uid))
    await update.message.reply_text(
        f"✅ *Daily Free Access ပေးပြီးပါပြီ*\n\n"
        f"👤 User ID: `{uid}`\n"
        f"🎁 ယနေ့ကျန်ချိန်: *{format_free_time(remaining)}*\n\n"
        "Signal တောင်းမှ timer စပါမယ်။ Stop လုပ်ထားရင် အချိန်မဆက်တွက်ပါ။",
        parse_mode=ParseMode.MARKDOWN,
    )
    try:
        await _send_text_retry(
            ctx.bot,
            int(uid),
            "🎁 Admin က သင့်အတွက် ယနေ့ Daily Free Access ၁ နာရီ ခွင့်ပြုထားပါတယ်။\n"
            "Signal တောင်းမှ timer စပါမယ်။",
        )
    except Exception as e:
        logger.warning(f"Could not notify free-access user {uid}: {e}")

async def _do_remove_free(update: Update, ctx: ContextTypes.DEFAULT_TYPE, text: str):
    ctx.user_data["state"] = None
    try:
        uid = str(int(text.strip()))
    except ValueError:
        await update.message.reply_text("❌ User ID က ဂဏန်းဖြစ်ရပါမည်")
        return

    data = load_free_access()
    record = data.get(uid)
    if not isinstance(record, dict) or not record.get("enabled", False):
        await update.message.reply_text(
            f"❌ User `{uid}` အတွက် Free Access မရှိပါ",
            parse_mode=ParseMode.MARKDOWN,
        )
        return
    record["enabled"] = False
    record["active"] = False
    record["started_at"] = None
    save_free_access(data)
    await update.message.reply_text(
        f"✅ *Free Access ဖယ်ပြီးပါပြီ*\n\n👤 User ID: `{uid}`",
        parse_mode=ParseMode.MARKDOWN,
    )

async def _do_remove_vip(update: Update, ctx: ContextTypes.DEFAULT_TYPE, text: str):
    ctx.user_data["state"] = None
    try: uid = str(int(text.strip()))
    except ValueError:
        await update.message.reply_text("❌ ဂဏန်းဖြစ်ရပါမည်"); return
    vip = load_vip()
    if uid not in vip:
        await update.message.reply_text(f"❌ User `{uid}` VIP List ထဲမရှိပါ", parse_mode=ParseMode.MARKDOWN); return
    name = vip[uid].get("first_name", "Unknown"); del vip[uid]; save_vip(vip)
    await update.message.reply_text(f"✅ *VIP Removed!*\n\n👤 ID: `{uid}`\n📛 Name: {name}", parse_mode=ParseMode.MARKDOWN)

async def _do_broadcast(update: Update, ctx: ContextTypes.DEFAULT_TYPE, text: str):
    ctx.user_data["state"] = None
    vip = load_vip(); success = 0; fail = 0
    for uid in list(vip.keys()):
        try:
            await ctx.bot.send_message(int(uid), f"📢 *Broadcast*\n\n{text}", parse_mode=ParseMode.MARKDOWN)
            success += 1
        except Exception: fail += 1
        await asyncio.sleep(0.05)
    await update.message.reply_text(f"📢 *Broadcast Complete!*\n\n✅ Sent: {success}\n❌ Failed: {fail}", parse_mode=ParseMode.MARKDOWN)


async def error_handler(update: object, context: ContextTypes.DEFAULT_TYPE):
    """Log unexpected update errors so one bad update cannot stop polling."""
    error = context.error
    if error:
        logger.error("Unhandled Telegram update error: %s", error, exc_info=error)


# ── Bot setup ──────────────────────────────────────────────────────────────────

async def post_init(app: Application):
    await app.bot.set_my_commands([
        BotCommand("start", "Bot စတင်ရန် / ကြိုဆိုစာ"),
        BotCommand("myid",  "သင်၏ Telegram ID ကြည့်ရန်"),
    ])
    for admin_id in ADMIN_IDS:
        await _set_admin_commands(app.bot, admin_id)
    app.create_task(auto_post_loop(app))
    logger.info("✅ Bot initialized")

def main():
    validate_configuration()
    app = Application.builder().token(BOT_TOKEN).post_init(post_init).build()
    app.add_handler(CommandHandler("start", cmd_start))
    app.add_handler(CommandHandler("myid",  cmd_myid))
    app.add_handler(CommandHandler("admin", cmd_admin))
    app.add_handler(CallbackQueryHandler(handle_callback))
    app.add_handler(MessageHandler(filters.UpdateType.CHANNEL_POSTS, handle_channel_post))
    app.add_handler(MessageHandler(filters.PHOTO & filters.ChatType.PRIVATE, handle_admin_photo))
    app.add_handler(MessageHandler(filters.Sticker.ALL & filters.ChatType.PRIVATE, handle_admin_sticker))
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, handle_message))
    # Keep this after the text/photo/sticker handlers so it only catches
    # forwarded media types that do not have a more specific handler.
    app.add_handler(MessageHandler(filters.ALL & filters.ChatType.PRIVATE, handle_admin_forwarded))
    app.add_error_handler(error_handler)
    logger.info("🤖 Dr Thet Pyinn Signals Bot starting...")
    app.run_polling(allowed_updates=Update.ALL_TYPES, drop_pending_updates=True)

if __name__ == "__main__":
    main()
